input.script:
listing = boundary retry 2 {
    return list_tickets({ page: 1, status: "open" })
} catch err {
    return fail("LIST_FAILED", err.code + ": " + err.message)
}
remaining = for page in list.range(2, listing.total_pages + 1) {
    result = boundary retry 2 { return list_tickets({ page: page, status: "open" }) } catch err {
        return fail("LIST_FAILED", err.code + ": " + err.message)
    }
    return result.items
}
all_open = fold acc = listing.items for page_items in remaining {
    return acc + page_items
}
cutoff_ms = time.parse("2026-06-03T00:00:00Z")
candidates = for t in all_open {
    created_ms = time.parse(t.created_at)
    skip if created_ms >= cutoff_ms
    return t
}
escalated = for t in candidates {
    detail = get_ticket({ id: t.id })
    body_lower = text.lower(detail.body if detail.body != null else "")
    skip if not ("refund" in body_lower)
    updated = update_ticket({ id: t.id, priority: "high", add_tags: ["billing-escalation"] })
    return t.id
}
return { escalated_ticket_ids: list.sort(escalated), checked: list.length(candidates), total_open: list.length(all_open) }
